import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(ch) for ch in data[2 + i]] for i in range(r)]
q = int(data[2 + r])
D4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
D8 = D4 + ((1, 1), (1, -1), (-1, 1), (-1, -1))
res = []
for k in range(q):
    x, y = int(data[3 + r + 2 * k]), int(data[4 + r + 2 * k])
    S = {(x, y)}
    st = [(x, y)]
    while st:
        a, b = st.pop()
        for da, db in D8:
            na, nb = a + da, b + db
            if 0 <= na < r and 0 <= nb < c and g[na][nb] == 1 and (na, nb) not in S:
                S.add((na, nb))
                st.append((na, nb))
    # flood the ocean treating everything except S as passable
    outside = set()
    st = []
    for i in range(r):
        for j in range(c):
            if (i == 0 or j == 0 or i == r - 1 or j == c - 1) and (i, j) not in S:
                outside.add((i, j))
                st.append((i, j))
    while st:
        a, b = st.pop()
        for da, db in D4:
            na, nb = a + da, b + db
            if 0 <= na < r and 0 <= nb < c and (na, nb) not in S and (na, nb) not in outside:
                outside.add((na, nb))
                st.append((na, nb))
    enclosed_water = {(i, j) for i in range(r) for j in range(c) if g[i][j] == 0 and (i, j) not in outside}
    seen = set()
    lakes = 0
    for cell in enclosed_water:
        if cell in seen:
            continue
        comp = {cell}
        seen.add(cell)
        st = [cell]
        touches = False
        while st:
            a, b = st.pop()
            for da, db in D4:
                na, nb = a + da, b + db
                if (na, nb) in S:
                    touches = True
                if (na, nb) in enclosed_water and (na, nb) not in seen:
                    seen.add((na, nb))
                    st.append((na, nb))
        if touches:
            lakes += 1
    res.append(lakes)
print('\n'.join(map(str, res)))

