def gen(rng):
    def fmt(g, queries):
        return f'{len(g)} {len(g[0])}\n' + '\n'.join(''.join(map(str, row)) for row in g) + f'\n{len(queries)}\n' + '\n'.join(f'{x} {y}' for x, y in queries)
    def land_cells(g):
        return [(i, j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j] == 1]
    def with_queries(g, q):
        cells = land_cells(g)
        if not cells:
            g[rng.randrange(len(g))][rng.randrange(len(g[0]))] = 1
            cells = land_cells(g)
        return fmt(g, [rng.choice(cells) for _ in range(q)])
    tests = []
    tests.append('5 8\n00000000\n01110110\n01010100\n01110110\n00000000\n2\n1 1\n1 5')
    tests.append('1 1\n1\n1\n0 0')
    tests.append('3 3\n111\n101\n111\n2\n0 0\n2 2')
    tests.append('3 3\n010\n101\n010\n1\n1 0')
    tests.append('4 4\n1111\n1001\n1001\n1111\n1\n0 0')
    tests.append('3 4\n1111\n1010\n1111\n1\n1 2')
    for _ in range(80):
        r = rng.randint(1, 9)
        c = rng.randint(1, 9)
        p = rng.choice([0.3, 0.45, 0.6, 0.75])
        g = [[1 if rng.random() < p else 0 for _ in range(c)] for _ in range(r)]
        tests.append(with_queries(g, rng.randint(1, 6)))
    # nested rings
    for size in (11, 15, 19):
        g = [[0] * size for _ in range(size)]
        k = 0
        while 2 * k < size:
            if k % 2 == 0:
                for i in range(k, size - k):
                    for j in range(k, size - k):
                        if i in (k, size - k - 1) or j in (k, size - k - 1):
                            g[i][j] = 1
            k += 1
        tests.append(with_queries(g, 6))
    # large: random land at several densities
    for p in (0.55, 0.35, 0.47):
        g = [[1 if rng.random() < p else 0 for _ in range(500)] for _ in range(500)]
        tests.append(with_queries(g, 100000))
    # large: concentric rings (deep nesting)
    n = 499
    g = [[0] * n for _ in range(n)]
    for k in range(0, n // 2 + 1, 2):
        for i in range(k, n - k):
            for j in range(k, n - k):
                if i in (k, n - k - 1) or j in (k, n - k - 1):
                    g[i][j] = 1
    tests.append(with_queries(g, 100000))
    # large: checkerboard, one island with huge numbers of tiny lakes
    g = [[(i + j) % 2 for j in range(500)] for i in range(500)]
    tests.append(with_queries(g, 100000))
    return tests

